// Une image carrée compressée, séparée de la progression et jamais envoyée à un serveur.
export const AVATAR_KEY='pokeluck-avatar-v1';
export const DEFAULT_AVATAR='https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/25.png';
export function getAvatar(){try{const value=localStorage.getItem(AVATAR_KEY);if(value?.length<500000&&/^data:image\/jpeg;base64,[A-Za-z0-9+/=]+$/.test(value))return value;}catch{}return DEFAULT_AVATAR;}
export function applyAvatar(){const image=document.querySelector('#edit-profile img');if(image){const src=getAvatar();image.src=src;image.alt=src===DEFAULT_AVATAR?'Avatar Pikachu':'Photo de profil du dresseur';image.classList.toggle('custom-avatar',src!==DEFAULT_AVATAR);}}
// Coordonnées source bornées : le carré reste toujours rempli, même au zoom maximal.
export function cropRect(width,height,zoom,x,y){const side=Math.min(width,height)/zoom;return {sx:(width-side)*(x+1)/2,sy:(height-side)*(y+1)/2,side};}
export function mountAvatar(host){
 host.innerHTML=`<div class="avatar-setting"><img class="avatar-preview" alt="Photo de profil actuelle" width="68" height="68"><div><button type="button" class="setting-wide-button" data-avatar-pick>Importer une photo</button><button type="button" class="avatar-reset" data-avatar-reset>Remettre Pikachu</button></div></div><input type="file" accept="image/jpeg,image/png,image/webp" hidden aria-label="Choisir une photo de profil"><small class="setting-footnote">JPG, PNG ou WebP · 10 Mo maximum. Recadrage avant confirmation, stockage dans ce navigateur.</small><div class="avatar-crop" hidden><h5>Recadrer ma photo</h5><p>Déplace la photo avec la souris ou le doigt, puis ajuste le zoom.</p><canvas width="280" height="280" aria-label="Aperçu carré du recadrage"></canvas><label>Zoom <input type="range" min="1" max="4" step="0.01" value="1" data-crop="zoom"></label><label>Position horizontale <input type="range" min="-1" max="1" step="0.01" value="0" data-crop="x"></label><label>Position verticale <input type="range" min="-1" max="1" step="0.01" value="0" data-crop="y"></label><div class="avatar-actions"><button type="button" class="primary" data-avatar-confirm>Confirmer la photo</button><button type="button" class="setting-wide-button" data-avatar-cancel>Annuler</button></div></div><p class="avatar-message" role="status" aria-live="polite"></p>`;
 const $=s=>host.querySelector(s),file=$('input[type=file]'),editor=$('.avatar-crop'),canvas=$('canvas'),ctx=canvas.getContext('2d'),message=$('.avatar-message');
 let image=null,zoom=1,x=0,y=0,drag=null,token=0;
 const preview=()=>{$('.avatar-preview').src=getAvatar();$('[data-avatar-reset]').hidden=getAvatar()===DEFAULT_AVATAR;};preview();
 function draw(){if(!image)return;const r=cropRect(image.naturalWidth,image.naturalHeight,zoom,x,y);ctx.fillStyle='#ffffff';ctx.fillRect(0,0,280,280);ctx.drawImage(image,r.sx,r.sy,r.side,r.side,0,0,280,280);host.querySelectorAll('[data-crop]').forEach(el=>el.value=({zoom,x,y})[el.dataset.crop]);}
 function cancel(){token++;image=null;drag=null;editor.hidden=true;file.value='';$('[data-avatar-pick]').focus();}
 $('[data-avatar-pick]').onclick=()=>file.click();
 file.onchange=async()=>{const selected=file.files[0];if(!selected)return;const current=++token;image=null;editor.hidden=true;message.textContent='';if(!['image/jpeg','image/png','image/webp'].includes(selected.type)||selected.size>10*1024*1024){message.textContent='Choisis une image JPG, PNG ou WebP de 10 Mo maximum.';file.value='';return;}
 const url=URL.createObjectURL(selected);try{const img=new Image();img.src=url;await img.decode();if(current!==token||!host.isConnected)return;if(!img.naturalWidth||!img.naturalHeight||img.naturalWidth*img.naturalHeight>40000000)throw new Error('dimensions');image=img;zoom=1;x=y=0;draw();editor.hidden=false;$('[data-crop="zoom"]').focus();}catch{if(current===token)message.textContent='Cette image ne peut pas être ouverte. Essaie une autre photo (40 mégapixels maximum).';}finally{URL.revokeObjectURL(url);file.value='';}};
 host.querySelectorAll('[data-crop]').forEach(el=>el.oninput=()=>{const value=+el.value;if(el.dataset.crop==='zoom')zoom=value;else if(el.dataset.crop==='x')x=value;else y=value;draw();});
 canvas.onpointerdown=e=>{if(!image)return;drag={id:e.pointerId,x:e.clientX,y:e.clientY,startX:x,startY:y};canvas.setPointerCapture(e.pointerId);};
 canvas.onpointermove=e=>{if(!drag||drag.id!==e.pointerId||!image)return;const side=Math.min(image.naturalWidth,image.naturalHeight)/zoom,scale=side/canvas.getBoundingClientRect().width;const dx=image.naturalWidth-side,dy=image.naturalHeight-side;x=dx?Math.max(-1,Math.min(1,drag.startX-2*(e.clientX-drag.x)*scale/dx)):0;y=dy?Math.max(-1,Math.min(1,drag.startY-2*(e.clientY-drag.y)*scale/dy)):0;draw();};
 canvas.onpointerup=canvas.onpointercancel=()=>{drag=null;};
 $('[data-avatar-cancel]').onclick=()=>{cancel();message.textContent='Modification annulée.';};
 $('[data-avatar-confirm]').onclick=()=>{if(!image)return;try{const output=document.createElement('canvas');output.width=output.height=256;output.getContext('2d').drawImage(canvas,0,0,256,256);localStorage.setItem(AVATAR_KEY,output.toDataURL('image/jpeg',0.88));applyAvatar();preview();cancel();message.textContent='Photo de profil enregistrée.';}catch{message.textContent='Impossible d’enregistrer : le stockage du navigateur est plein ou indisponible. Ta photo précédente est conservée.';}};
 $('[data-avatar-reset]').onclick=()=>{try{localStorage.removeItem(AVATAR_KEY);applyAvatar();preview();cancel();message.textContent='Pikachu est de retour.';}catch{message.textContent='Le stockage du navigateur est indisponible.';}};
}

